"""Quality-gate settings generated by the build (M2.2): no hand-maintained duplicate manifests.

The code that draws a figure declares what it is, once, and the gate settings are written from those declarations:

    from kit.gates import Gates
    G = Gates(words=ART / "words.json", finance=scenario)       # scenario: kit.finmodel.Scenario (optional)

    short = G.value("peak_shortfall", financing=False)           # the number comes from the model ...
    svg += f'<g{G.fig("short", f"${short:,.0f} short", cue=["18,000"], after=24, shows="peak_shortfall", financing=False)}>'
    #      ... and the same call registers the figure for figure_check and the claim for the finance validator
    svg += f'<g{G.chart("profit-bars", cue=["profit"], after=14, offset=.5)}>'
    svg += f'<rect{G.mark("profit-bars", 18000)} .../>'          # chart marks carry their values

    G.write(WORKSPACE, scenes=scenes, video=OUT_MP4)             # → WORKSPACE/gates/gates.json (+ figures, finance,
                                                                 #   interactions); run scripts/quality_gates.py on it

Contacts are not declared here at all: contact_check.mjs reads them from the built composition (every R4.hold, and
anything pushed to window.__gates.contacts by other systems), so the hold that animates a prop is also the hold that
is checked. Cues are validated against the narration word timings when declared, so a manifest can never name a word
that is not spoken. Original implementation.
"""
from __future__ import annotations

import json
import re
from dataclasses import asdict
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]


def _norm(s: str) -> str:
    return re.sub(r"[^a-z0-9]", "", str(s).lower())


def _rel(p: Path | str | None) -> str | None:
    if p is None:
        return None
    p = Path(p).resolve()
    try:
        return str(p.relative_to(ROOT))
    except ValueError:
        return str(p)


class Gates:
    def __init__(self, words: Path | str, finance=None, treatment: Path | str | None = None):
        self.words_path = Path(words)
        # the episode's creative treatment (STANDARD §3A): found beside the artifacts folder unless given
        t = Path(treatment) if treatment else self.words_path.resolve().parent.parent / "treatment.json"
        self.treatment = t if t.exists() else None
        self.words = json.loads(self.words_path.read_text())
        self.scenario = finance
        self._model = {}
        self.figures: list[dict] = []
        self.charts: dict[str, dict] = {}
        self.claims: list[dict] = []
        self.events: list[dict] = []

    # ── numbers come from the model ──────────────────────────────────────────────────────────────────────────────
    def value(self, key: str, day: int | None = None, financing: bool = True) -> float:
        if self.scenario is None:
            raise ValueError("Gates(finance=...) is needed to read model values")
        from .finmodel import simulate
        if financing not in self._model:
            self._model[financing] = simulate(self.scenario, financing)
        return self._model[financing].metric(key, day)

    def cue_time(self, cue, after: float = 0.0) -> float:
        want = {_norm(c) for c in ([cue] if isinstance(cue, str) else cue)}
        for w in self.words:
            if w["start"] >= after - 1e-6 and _norm(w["word"]) in want:
                return w["start"]
        raise KeyError(f"cue {cue!r} is not spoken after {after}s")

    # ── declarations (each returns the attribute string to put on the element) ──────────────────────────────────
    def fig(self, fid: str, text: str, cue, after: float = 0.0, *, shows: str | None = None, day: int | None = None,
            financing: bool = True, value: float | None = None, settle: float | None = None, hold: float | None = None,
            lead: float | None = None) -> str:
        """A figure the narration names. `text` must appear in the element when it is legible. If `shows` names a
        model metric, the figure is also a financial claim checked by the validator (value defaults to the model's)."""
        if any(f["id"] == fid for f in self.figures):
            raise ValueError(f"duplicate figure id {fid!r}")
        cue = [cue] if isinstance(cue, str) else list(cue)
        self.cue_time(cue, after)                                   # fail at build time, not in QA
        f = {"id": fid, "sel": f'[data-gate-fig="{fid}"]', "text": text, "cue": cue, "after": after}
        for k, v in (("settle", settle), ("hold", hold), ("lead", lead)):
            if v is not None:
                f[k] = v
        self.figures.append(f)
        if shows:
            v = self.value(shows, day, financing) if value is None else value
            c = {"id": fid, "shows": shows, "value": v, "financing": financing}
            if day is not None:
                c["day"] = day
            self.claims.append(c)
        return f' data-gate-fig="{fid}"'

    def chart(self, cid: str, *, cue=None, after: float = 0.0, offset: float = 0.0, t: float | None = None,
              measure: str = "height", baseline: str = "bottom") -> str:
        """A chart whose marks encode values. Checked at the cue (+offset) or at time t."""
        if cid in self.charts:
            raise ValueError(f"duplicate chart id {cid!r}")
        if t is None and cue is None:
            raise ValueError("chart needs cue= or t=")
        at = {"t": t} if t is not None else {"cue": [cue] if isinstance(cue, str) else list(cue), "after": after, "offset": offset}
        if cue is not None:
            self.cue_time(at["cue"], after)
        self.charts[cid] = {"id": cid, "at": at, "measure": measure, "baseline": baseline, "marks": []}
        return f' data-gate-chart="{cid}"'

    def mark(self, cid: str, value: float) -> str:
        ch = self.charts[cid]
        k = f"{cid}:{len(ch['marks'])}"
        ch["marks"].append({"sel": f'[data-gate-mark="{k}"]', "value": value})
        return f' data-gate-mark="{k}"'

    def event(self, t: float, eid: str, label: str, box: list | None = None):
        """An extra moment for the review contact sheets (holds and cuts are added automatically)."""
        e = {"id": eid, "t": t, "label": label}
        if box:
            e["box"] = box
        self.events.append(e)

    # ── output ──────────────────────────────────────────────────────────────────────────────────────────────────
    def write(self, ws: Path | str, *, scenes=None, video: Path | str | None = None, layout_every: float = 0.25) -> Path:
        ws = Path(ws)
        d = ws / "gates"
        d.mkdir(parents=True, exist_ok=True)
        cfg = {"_generated": "by kit/gates.py from the episode build; do not edit (rebuild instead)",
               "workspace": _rel(ws / "index.html"), "words": _rel(self.words_path), "contacts": "auto",
               "layout_every": layout_every}
        if video:
            cfg["video"] = _rel(video)
        if self.treatment:
            cfg["treatment"] = _rel(self.treatment)
        figs = {"figures": self.figures, "charts": [c for c in self.charts.values() if c["marks"]]}
        empty = [c["id"] for c in self.charts.values() if not c["marks"]]
        if empty:
            raise ValueError(f"chart(s) without marks: {empty}")
        if figs["figures"] or figs["charts"]:
            (d / "figures.json").write_text(json.dumps(figs, indent=2, ensure_ascii=False))
            cfg["figures"] = _rel(d / "figures.json")
        if self.scenario is not None:
            (d / "finance.json").write_text(json.dumps({"scenario": asdict(self.scenario), "figures": self.claims}, indent=2, ensure_ascii=False))
            cfg["finance"] = _rel(d / "finance.json")
        cuts = sorted({round(float(s.start), 3) for s in (scenes or []) if float(s.start) > 0})
        (d / "interactions.json").write_text(json.dumps({"interactions": self.events, "cuts": cuts}, indent=2))
        cfg["interactions"] = _rel(d / "interactions.json")
        (d / "gates.json").write_text(json.dumps(cfg, indent=2))
        return d / "gates.json"
